1	"use client";
2	
3	import { useState } from "react";
4	import { cn } from "@/lib/utils";
5	
6	/**
7	 * Each swatch is a colour FAMILY, and every `id` here must be a key of
8	 * `COLOR_FAMILIES` in `lib/generator/color.ts` — that is what turns a swatch
9	 * into the set of tag words Haiku actually writes ("charcoal", "khaki", …).
10	 * Matching these ids against item colours literally is what made the picker
11	 * return nothing.
12	 */
13	const PALETTE = [
14	  { id: "neutral", hex: "#8C8578" },
15	  { id: "camel", hex: "#C6A374" },
16	  { id: "navy", hex: "#2C3A4C" },
17	  { id: "olive", hex: "#6E6F52" },
18	  { id: "dark", hex: "#2B2A2E" },
19	];
20	
21	export function RefineSheet({
22	  open,
23	  occasionLabel,
24	  onApply,
25	  onClose,
26	}: {
27	  open: boolean;
28	  occasionLabel: string;
29	  onApply: (r: { formality: number; lean: string[] }) => void;
30	  onClose: () => void;
31	}) {
32	  const [formality, setFormality] = useState(3);
33	  const [colors, setColors] = useState<string[]>([]);
34	  if (!open) return null;
35	
36	  return (
37	    <>
38	      <button
39	        type="button"
40	        aria-label="Close"
41	        onClick={onClose}
42	        // `fixed`, not `absolute`: as a child of <main> this was clipped by that
43	        // element's `overflow-hidden` and, at z-30, painted UNDER the bottom nav
44	        // (z-50) — which covered the colour palette and the Apply button.
45	        className="fixed inset-0 z-[60] bg-[rgba(6,6,8,0.5)] backdrop-blur-[1.5px]"
46	      />
47	      <div
48	        role="dialog"
49	        aria-label="Refine the looks"
50	        className="fixed inset-x-0 bottom-0 z-[70] mx-auto max-w-[440px] rounded-t-[22px] border-t border-[rgba(237,230,216,0.12)] bg-surface-2 px-[18px] pb-[calc(env(safe-area-inset-bottom)+20px)] pt-3.5"
51	      >
52	        <div className="mx-auto mb-3 h-1 w-[34px] rounded-full bg-faint" />
53	        <h4 className="font-serif text-[19px] text-foreground">Refine the looks</h4>
54	        <p className="mb-4 text-xs text-muted-dim">Dressing for {occasionLabel} — nudge the rest.</p>
55	
56	        <p className="mb-2 text-[9px] uppercase tracking-[0.16em] text-muted-dim">Formality</p>
57	        <div className="flex gap-[5px]">
58	          {[1, 2, 3, 4, 5].map((n) => (
59	            <button
60	              key={n}
61	              type="button"
62	              aria-pressed={formality === n}
63	              onClick={() => setFormality(n)}
64	              className={cn(
65	                "h-8 flex-1 rounded-[9px] border text-xs transition-colors",
66	                formality === n
67	                  ? "border-brand/50 bg-brand/15 font-semibold text-brand-high"
68	                  : "border-[rgba(237,230,216,0.12)] text-muted-foreground",
69	              )}
70	            >
71	              {n}
72	            </button>
73	          ))}
74	        </div>
75	
76	        <p className="mb-2 mt-[15px] text-[9px] uppercase tracking-[0.16em] text-muted-dim">Lean into</p>
77	        <div className="flex gap-2.5">
78	          {PALETTE.map((c) => {
79	            const on = colors.includes(c.id);
80	            return (
81	              <button
82	                key={c.id}
83	                type="button"
84	                aria-label={c.id}
85	                aria-pressed={on}
86	                onClick={() => setColors((cur) => (on ? cur.filter((x) => x !== c.id) : [...cur, c.id]))}
87	                style={{ background: c.hex }}
88	                className={cn(
89	                  "h-[30px] w-[30px] rounded-full ring-inset",
90	                  on ? "ring-2 ring-brand" : "ring-1 ring-[rgba(237,230,216,0.12)]",
91	                )}
92	              />
93	            );
94	          })}
95	        </div>
96	
97	        <button
98	          type="button"
99	          onClick={() => onApply({ formality, lean: colors })}
100	          className="mt-[18px] w-full rounded-[12px] bg-foreground py-3.5 text-sm font-semibold text-canvas"
101	        >
102	          Show 3 looks
103	        </button>
104	      </div>
105	    </>
106	  );
107	}
